package org.carlife.hulab;
import java.io.*;
import java.net.SocketTimeoutException;
import java.util.*;
public final class MdWireTest {
 static int count;
 static void check(boolean b,String why){count++;if(!b)throw new AssertionError(why);}
 static byte[] hex(String s){byte[] b=new byte[s.length()/2];for(int i=0;i<b.length;i++)b[i]=(byte)Integer.parseInt(s.substring(i*2,i*2+2),16);return b;}
 static DataInputStream stream(byte[] b){return new DataInputStream(new ByteArrayInputStream(b));}
 interface Checked{void run()throws Exception;}
 static void rejects(Checked fn,String why)throws Exception{try{fn.run();throw new AssertionError("accepted "+why);}catch(IOException expected){count++;}}
 public static void main(String[] a)throws Exception{
  // Hand-authored fixtures from pinned outer >II and CMD >HHI, not generated by codec under test.
  byte[] version=hex("000000010000000c000400000001800108011000");
  byte[] match=hex("000000010000000a00020000000100020801");
  check(Arrays.equals(MdMain.packet(1,0x10002,new byte[]{8,1},0),match),"match golden");
  final MdMain.Frame f=MdMain.readFrame(stream(version));check(f.channel==1&&f.id==0x18001&&Arrays.equals(f.payload,hex("08011000")),"version golden");
  DataInputStream fragmented=new DataInputStream(new FilterInputStream(new ByteArrayInputStream(version)){public int read(byte[] b,int off,int len)throws IOException{return super.read(b,off,Math.min(len,1));}});
  check(MdMain.readFrame(fragmented).id==0x18001,"fragmented bytes");
  ByteArrayOutputStream combo=new ByteArrayOutputStream();combo.write(version);combo.write(match);DataInputStream joined=stream(combo.toByteArray());check(MdMain.readFrame(joined).id==0x18001&&MdMain.readFrame(joined).id==0x10002,"coalesced");
  for(int i=0;i<version.length;i++){final byte[] truncated=Arrays.copyOf(version,i);rejects(new Checked(){public void run()throws Exception{MdMain.readFrame(stream(truncated));}},"EOF@"+i);}
  rejects(new Checked(){public void run()throws Exception{MdMain.readFrame(stream(hex("0000000100100001")));}},"oversize before allocation");
  rejects(new Checked(){public void run()throws Exception{MdMain.readFrame(stream(hex("0000000700000008")));}},"unknown channel");
  rejects(new Checked(){public void run()throws Exception{MdMain.readFrame(stream(hex("00000001000000080000000100018009")));}},"reserved nonzero");
  rejects(new Checked(){public void run()throws Exception{MdMain.readFrame(stream(hex("00000001000000080001000000018009")));}},"inner mismatch");
  rejects(new Checked(){public void run()throws Exception{MdMain.Proto.parse(hex("08ffffffffffffffffffff02"));}},"varint overflow");
  rejects(new Checked(){public void run()throws Exception{MdMain.Proto.parse(hex("120341"));}},"truncated string");
  check(MdMain.Proto.number(MdMain.Proto.parse(hex("08011000")),1,0)==1,"proto2 version");
  DataInputStream idle=new DataInputStream(new InputStream(){public int read()throws IOException{throw new SocketTimeoutException("idle");}});check(MdMain.readFrame(idle)==null,"idle retry");
  rejects(new Checked(){public void run()throws Exception{MdMain.readFrame(new DataInputStream(new InputStream(){int n;public int read()throws IOException{if(n++==0)return 0;throw new SocketTimeoutException("partial header");}}));}},"timeout after first byte fatal");
  // Match=2 is from independently inspected MD reference constants, not an enum in .proto.
  check(MdMain.versionMatchStatus(MdMain.Proto.parse(hex("08011000")))==1,"version1.0 match");
  check(MdMain.versionMatchStatus(MdMain.Proto.parse(hex("08021000")))==2,"version2.0 rejected with status2");
  check(Arrays.equals(MdMain.packet(1,0x10002,MdMain.Proto.ints(1,2),0),hex("000000010000000a00020000000100020802")),"version mismatch golden2");
  rejects(new Checked(){public void run()throws Exception{MdMain.readFrame(stream(hex("00000001000000080000000000068008")));}},"message ID/channel mismatch");
  rejects(new Checked(){public void run()throws Exception{MdMain.versionMatchStatus(MdMain.Proto.parse(hex("0801")));}},"required minor version missing");
  rejects(new Checked(){public void run()throws Exception{MdMain.Proto.requireInts(MdMain.Proto.parse(hex("0801")),1,2,3);}},"required video/touch fields missing");
  rejects(new Checked(){public void run()throws Exception{MdMain.Proto.requireInts(MdMain.Proto.parse(new byte[0]),1);}},"required hardkey missing");
  rejects(new Checked(){public void run()throws Exception{MdMain.Proto.requireInts(MdMain.Proto.parse(hex("0a0131")),1);}},"wrong field wire type");
  rejects(new Checked(){public void run()throws Exception{MdMain.rejectMandatoryAuth(0x18048);}},"mandatory authentication request without provider");
  rejects(new Checked(){public void run()throws Exception{MdMain.rejectMandatoryAuth(0x1804a);}},"mandatory authentication result without provider");
  rejects(new Checked(){public void run()throws Exception{MdMain.rejectMandatoryAuth(0x1806b);}},"RSA encryption branch without provider");
  rejects(new Checked(){public void run()throws Exception{MdMain.rejectMandatoryAuth(0x1806d);}},"AES encryption branch without provider");
  rejects(new Checked(){public void run()throws Exception{MdMain.rejectMandatoryAuth(0x1806f);}},"encrypted-ready branch without provider");
  check(MdMain.androidKeyCodeForCarLife(1)==3,"pinned CarLife HOME1 maps AndroidHOME3");
  check(MdMain.androidKeyCodeForCarLife(14)==4,"pinned CarLife BACK14 maps AndroidBACK4");
  check(MdMain.androidKeyCodeForCarLife(3)==-1,"unknown hardkey not guessed");
  check(MdMain.sameVideoGeneration(7,7),"current child epoch accepted");
  check(!MdMain.sameVideoGeneration(7,8),"stopped child epoch rejected before enqueue/write");
  check(!MdMain.sameVideoGeneration(7,9),"old child rejected after reset and new start");
  check(MdMain.sameVideoGeneration(9,9),"new child epoch accepted");
  System.out.println("PASS "+count+" MD codec checks (no Android/device I/O)");
 }
}
